import { buildPdfPayload } from '@/entities/gauge-config/lib/build-pdf-payload';
import { deriveAccuracyClass } from '@/entities/gauge-config/lib/derive-accuracy';
import { deriveModelName } from '@/entities/gauge-config/lib/derive-model';
import { deriveVisualLayout } from '@/entities/gauge-config/lib/derive-visual-layout';
import { RANGE_PRESETS } from '@/entities/gauge-config/model/catalogs';
import type { GaugeConfiguratorState, PreviewBadge } from '@/entities/gauge-config/model/types';

export const selectModelName = (config: GaugeConfiguratorState) => deriveModelName(config.case.filling);

export const selectAccuracyClass = (config: GaugeConfiguratorState) =>
  deriveAccuracyClass(config.nominalSize);

export const selectRangeLabel = (config: GaugeConfiguratorState) =>
  `${config.rangeMin} ... ${config.rangeMax} ${config.unit}`;

export const selectRangePreset = (config: GaugeConfiguratorState) =>
  RANGE_PRESETS.find((preset) => preset.min === config.rangeMin && preset.max === config.rangeMax) ?? null;

export const selectVisualLayout = (config: GaugeConfiguratorState) => deriveVisualLayout(config);

export const selectPreviewBadges = (config: GaugeConfiguratorState): PreviewBadge[] => {
  const badges: PreviewBadge[] = [
    { label: `NS ${config.nominalSize} mm`, tone: 'neutral' },
    { label: `Range ${config.rangeMin}..${config.rangeMax} ${config.unit}`, tone: 'neutral' },
    {
      label: config.connection.location === 'Lower' ? 'Radial connection' : 'Back connection',
      tone: 'info',
    },
  ];

  if (config.project.tagNumber.trim()) {
    badges.push({ label: `Tag ${config.project.tagNumber.trim()}`, tone: 'accent' });
  }

  if (config.accessories.valve.enabled) {
    badges.push({ label: `Valve ${config.accessories.valve.standard}`, tone: 'warning' });
  }

  if (config.accessories.siphon.enabled) {
    badges.push({ label: `Siphon ${config.accessories.siphon.standard}`, tone: 'warning' });
  }

  return badges;
};

export const selectPdfPayload = (config: GaugeConfiguratorState) => buildPdfPayload(config);

export const selectIsRangeValid = (config: GaugeConfiguratorState) =>
  Number.isFinite(config.rangeMin) &&
  Number.isFinite(config.rangeMax) &&
  config.rangeMax > config.rangeMin;

export const selectHasCriticalValidationErrors = (config: GaugeConfiguratorState) =>
  !selectIsRangeValid(config);

