import type { GaugeConfiguratorState, GaugeVisualLayout } from '@/entities/gauge-config/model/types';
import { ScaleTicks } from '@/entities/gauge-preview/ui/ScaleTicks';

type GaugePreviewSvgProps = {
  config: GaugeConfiguratorState;
  visual: GaugeVisualLayout;
};

const renderSiphon = (type: string) =>
  type.includes('Trumpet') ? (
    <g transform="translate(0 10)">
      <circle cx="20" cy="20" r="20" fill="none" stroke="#666" strokeWidth="8" />
      <path
        d="M 0 0 L 0 20 A 20 20 0 1 0 40 20 L 40 60"
        fill="none"
        stroke="#666"
        strokeWidth="8"
      />
      <path
        d="M 0 0 L 0 20 A 20 20 0 1 0 40 20 L 40 60"
        fill="none"
        stroke="#999"
        strokeWidth="3"
      />
    </g>
  ) : (
    <g transform="translate(0 10)">
      <path
        d="M 0 0 L 0 40 A 20 20 0 0 0 40 40 L 40 0"
        fill="none"
        stroke="#666"
        strokeWidth="8"
      />
      <path
        d="M 0 0 L 0 40 A 20 20 0 0 0 40 40 L 40 0"
        fill="none"
        stroke="#999"
        strokeWidth="3"
      />
    </g>
  );

const LowerConnectionAssembly = ({ config, visual }: GaugePreviewSvgProps) => (
  <g transform={`translate(0 ${visual.r})`}>
    <rect
      x={-visual.stemWidth}
      y="0"
      width={visual.stemWidth * 2}
      height={visual.stemLen * 0.4}
      fill="#bbb"
      stroke="#777"
    />
    <rect
      x={-visual.stemWidth * 0.8}
      y="0"
      width={visual.stemWidth * 1.6}
      height={visual.stemLen * 0.4}
      fill="#ccc"
    />
    <rect
      x={-visual.stemWidth * 0.7}
      y={visual.stemLen * 0.4}
      width={visual.stemWidth * 1.4}
      height={visual.stemLen * 0.6}
      fill="#bbb"
      stroke="#888"
    />

    <g transform={`translate(0 ${visual.stemLen})`}>
      {config.accessories.valve.enabled ? (
        <g>
          <rect
            x={-25 * visual.scale}
            y="0"
            width={50 * visual.scale}
            height={40 * visual.scale}
            rx="2"
            fill="#d4d4d4"
            stroke="#666"
          />
          <rect
            x={-40 * visual.scale}
            y={10 * visual.scale}
            width={30 * visual.scale}
            height={8 * visual.scale}
            rx="2"
            fill="#333"
          />
          <rect
            x={-15 * visual.scale}
            y={12 * visual.scale}
            width={15 * visual.scale}
            height={4 * visual.scale}
            fill="#666"
          />
          {config.accessories.valve.type.includes('Form A') ? (
            <g transform={`translate(${25 * visual.scale} ${20 * visual.scale})`}>
              <rect x="0" y="-5" width={10} height={10} fill="#bbb" stroke="#666" />
            </g>
          ) : null}
          <g transform={`translate(0 ${40 * visual.scale})`}>
            {config.accessories.siphon.enabled ? (
              <g>
                <rect
                  x={-visual.stemWidth * 0.6}
                  y="0"
                  width={visual.stemWidth * 1.2}
                  height="10"
                  fill="#bbb"
                  stroke="#777"
                />
                {renderSiphon(config.accessories.siphon.type)}
              </g>
            ) : (
              <g>
                <rect
                  x={-visual.stemWidth * 0.6}
                  y="0"
                  width={visual.stemWidth * 1.2}
                  height="15"
                  fill="#bbb"
                  stroke="#777"
                />
                <line x1="-10" y1="5" x2="10" y2="5" stroke="#888" />
                <line x1="-10" y1="10" x2="10" y2="10" stroke="#888" />
              </g>
            )}
          </g>
        </g>
      ) : null}
      {!config.accessories.valve.enabled && config.accessories.siphon.enabled ? (
        <g>{renderSiphon(config.accessories.siphon.type)}</g>
      ) : null}
    </g>
  </g>
);

const BackConnectionAssembly = ({ visual }: Pick<GaugePreviewSvgProps, 'visual'>) => (
  <g opacity="0.5">
    <circle r={visual.backConnectionRadius + 6} fill="#d7dce2" stroke="#9aa4b2" />
    <rect
      x={-visual.backConnectionRadius}
      y={-visual.backConnectionLength / 2}
      width={visual.backConnectionRadius * 2}
      height={visual.backConnectionLength}
      rx="4"
      fill="#cad2dc"
      stroke="#8791a0"
    />
    <circle r={visual.backConnectionRadius} fill="#bcc5d2" stroke="#8791a0" />
  </g>
);

const UClampMount = ({ visual }: Pick<GaugePreviewSvgProps, 'visual'>) => (
  <g opacity="0.9">
    <path
      d={`M ${-visual.r - 16} ${-visual.r * 0.1} q -18 10 -18 34 v ${visual.r * 0.45}`}
      fill="none"
      stroke="#8a8f98"
      strokeWidth="8"
      strokeLinecap="round"
    />
    <path
      d={`M ${visual.r + 16} ${-visual.r * 0.1} q 18 10 18 34 v ${visual.r * 0.45}`}
      fill="none"
      stroke="#8a8f98"
      strokeWidth="8"
      strokeLinecap="round"
    />
  </g>
);

export const GaugePreviewSvg = ({ config, visual }: GaugePreviewSvgProps) => (
  <svg
    width="100%"
    height="100%"
    viewBox={`0 0 ${visual.svgSize} ${visual.svgSize}`}
    preserveAspectRatio="xMidYMid meet"
  >
    <defs>
      <linearGradient id="caseGrad" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stopColor="#e0e0e0" />
        <stop offset="40%" stopColor="#f5f5f5" />
        <stop offset="100%" stopColor="#d4d4d4" />
      </linearGradient>
      <filter id="dropshadow" height="130%">
        <feGaussianBlur in="SourceAlpha" stdDeviation="3" />
        <feOffset dx="2" dy="2" result="offsetblur" />
        <feComponentTransfer>
          <feFuncA type="linear" slope="0.3" />
        </feComponentTransfer>
        <feMerge>
          <feMergeNode />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
      <clipPath id="gaugeFaceClip">
        <circle cx="0" cy="0" r={visual.rDial} />
      </clipPath>
    </defs>

    <g transform={`translate(${visual.cx} ${visual.cy})`}>
      {config.connection.location === 'Back' ? <BackConnectionAssembly visual={visual} /> : null}
      {config.options.flange.includes('Rear') ? (
        <circle r={visual.r + 15} fill="#d0d0d0" stroke="#999" strokeWidth="1" />
      ) : null}
      {config.options.flange.includes('Front') ? (
        <circle r={visual.r + 20} fill="#d8d8d8" stroke="#999" strokeWidth="1" />
      ) : null}
      {config.options.flange.includes('U-Clamp') ? <UClampMount visual={visual} /> : null}
      <circle r={visual.r} fill="url(#caseGrad)" stroke="#999" strokeWidth="1" filter="url(#dropshadow)" />
      {config.options.flange.includes('Front') ? (
        <g>
          {[0, 120, 240].map((angle) => (
            <g key={angle} transform={`rotate(${angle}) translate(0 ${-visual.r - 12})`}>
              <circle r="3" fill="#333" />
              <circle r="1.5" fill="#fff" opacity="0.3" />
            </g>
          ))}
        </g>
      ) : null}
      <circle r={visual.rInner} fill="none" stroke="#b0b0b0" strokeWidth="4" />
      <circle r={visual.rDial} fill="#fff" />

      {config.case.filling !== 'Dry' ? (
        <g clipPath="url(#gaugeFaceClip)">
          <path
            d={`M -${visual.rDial} -${visual.rDial * 0.6}
              Q 0 -${visual.rDial * 0.5} ${visual.rDial} -${visual.rDial * 0.6}
              L ${visual.rDial} ${visual.rDial}
              L -${visual.rDial} ${visual.rDial} Z`}
            fill={
              config.case.filling.includes('Silicone')
                ? 'rgba(200, 200, 250, 0.2)'
                : 'rgba(200, 255, 230, 0.3)'
            }
          />
          <path
            d={`M -${visual.rDial} -${visual.rDial * 0.6}
              Q 0 -${visual.rDial * 0.5} ${visual.rDial} -${visual.rDial * 0.6}`}
            stroke={
              config.case.filling.includes('Silicone')
                ? 'rgba(100, 100, 200, 0.2)'
                : 'rgba(100, 200, 150, 0.3)'
            }
            fill="none"
            strokeWidth="1"
          />
        </g>
      ) : null}

      <ScaleTicks radius={visual.rDial} min={config.rangeMin} max={config.rangeMax} />

      <text y={visual.rDial * 0.35} textAnchor="middle" className="fill-slate-800 text-sm font-black tracking-[0.4em]">
        DIN
      </text>
      <text y={visual.rDial * 0.5} textAnchor="middle" className="fill-slate-500 text-xs font-bold">
        {config.unit}
      </text>
      <text y={visual.rDial * 0.65} textAnchor="middle" className="fill-slate-400 text-[8px] font-bold">
        316L
      </text>

      {config.project.tagNumber.trim() ? (
        <>
          <rect
            x={-visual.rDial * 0.3}
            y={visual.rDial * 0.1}
            width={visual.rDial * 0.6}
            height="16"
            fill="rgba(255,255,255,0.84)"
            rx="2"
          />
          <text
            y={visual.rDial * 0.1 + 11}
            textAnchor="middle"
            className="fill-black font-mono text-[10px] font-bold uppercase tracking-tight"
          >
            {config.project.tagNumber.trim()}
          </text>
        </>
      ) : null}

      {config.case.window.includes('safety') ? (
        <g transform={`translate(0 ${-visual.rDial * 0.5}) scale(0.6)`}>
          <path d="M -10 0 L 0 -10 L 10 0 L 0 10 Z" fill="none" stroke="#000" strokeWidth="1.5" />
          <line x1="-5" y1="0" x2="5" y2="0" stroke="#000" strokeWidth="1.5" />
          <line x1="0" y1="-5" x2="0" y2="5" stroke="#000" strokeWidth="1.5" />
        </g>
      ) : null}

      {config.options.redPointer ? (
        <g transform={`rotate(${visual.redPointerRotation})`}>
          <polygon points="0,-10 4,-90 0,-95 -4,-90" fill="red" opacity="0.9" />
        </g>
      ) : null}

      <g transform={`rotate(${visual.pointerRotation})`} filter="url(#dropshadow)">
        <circle r="5" fill="#000" />
        <path d={`M -2 0 L -1 -${visual.rDial * 0.85} L 1 -${visual.rDial * 0.85} L 2 0 Z`} fill="#000" />
        <path d="M -3 0 L -4 15 L 4 15 L 3 0 Z" fill="#000" />
      </g>

      <circle r="2" fill="#888" />
      {config.connection.location === 'Lower' ? (
        <LowerConnectionAssembly config={config} visual={visual} />
      ) : null}
    </g>
  </svg>
);

