import { ArrowDownToLine, Move } from 'lucide-react';
import { CONNECTION_STANDARDS, MOUNTING_TYPES } from '@/entities/gauge-config/model/catalogs';
import { useGaugeConfiguratorStore } from '@/entities/gauge-config/model/store';
import { en } from '@/shared/i18n';
import { ChoiceButton } from '@/shared/ui/ChoiceButton';
import { Field } from '@/shared/ui/Field';
import { SectionCard } from '@/shared/ui/SectionCard';
import { SelectInput } from '@/shared/ui/SelectInput';

const BackConnectionGlyph = () => (
  <div className="flex h-5 w-5 items-center justify-center rounded-full border-2 border-current">
    <div className="h-1.5 w-1.5 rounded-full bg-current" />
  </div>
);

export const ConnectionMountingForm = () => {
  const connection = useGaugeConfiguratorStore((state) => state.config.connection);
  const flange = useGaugeConfiguratorStore((state) => state.config.options.flange);
  const setConnectionField = useGaugeConfiguratorStore((state) => state.setConnectionField);
  const setFlange = useGaugeConfiguratorStore((state) => state.setFlange);

  return (
    <SectionCard title={en.sections.connectionMounting} icon={Move} accentClass="text-emerald-400">
      <div className="space-y-5">
        <Field label={en.labels.connectionLocation}>
          <div className="grid grid-cols-2 gap-3">
            <ChoiceButton
              selected={connection.location === 'Lower'}
              onClick={() => setConnectionField('location', 'Lower')}
              className={connection.location === 'Lower' ? 'border-emerald-400 bg-emerald-500/15 text-emerald-200' : ''}
            >
              <span className="flex flex-col items-center gap-2">
                <ArrowDownToLine size={18} />
                <span>{en.actions.radial}</span>
              </span>
            </ChoiceButton>
            <ChoiceButton
              selected={connection.location === 'Back'}
              onClick={() => setConnectionField('location', 'Back')}
              className={connection.location === 'Back' ? 'border-emerald-400 bg-emerald-500/15 text-emerald-200' : ''}
            >
              <span className="flex flex-col items-center gap-2">
                <BackConnectionGlyph />
                <span>{en.actions.axial}</span>
              </span>
            </ChoiceButton>
          </div>
        </Field>

        <Field label={en.labels.mountingType} htmlFor="mounting-type">
          <SelectInput
            id="mounting-type"
            value={flange}
            onChange={(event) => setFlange(event.currentTarget.value as typeof flange)}
          >
            {MOUNTING_TYPES.map((mountingType) => (
              <option key={mountingType} value={mountingType}>
                {mountingType}
              </option>
            ))}
          </SelectInput>
        </Field>

        <Field label={en.labels.threadStandard} htmlFor="thread-standard">
          <SelectInput
            id="thread-standard"
            value={connection.standard}
            onChange={(event) =>
              setConnectionField('standard', event.currentTarget.value as typeof connection.standard)
            }
          >
            {CONNECTION_STANDARDS.map((standard) => (
              <option key={standard} value={standard}>
                {standard}
              </option>
            ))}
          </SelectInput>
        </Field>
      </div>
    </SectionCard>
  );
};

