import { deriveAccuracyClass } from '@/entities/gauge-config/lib/derive-accuracy';
import { deriveModelName } from '@/entities/gauge-config/lib/derive-model';
import type { GaugeConfiguratorState, PdfPayload } from '@/entities/gauge-config/model/types';

const safeText = (value: string | number | boolean | null | undefined, fallback = '-') =>
  `${value ?? ''}`.trim() || fallback;

export const buildPdfPayload = (
  config: GaugeConfiguratorState,
  generatedAt: Date = new Date(),
): PdfPayload => {
  const modelName = deriveModelName(config.case.filling);
  const orderNumber = config.project.orderNumber.trim();

  return {
    fileName: `Gauge_Spec_${orderNumber || 'Draft'}.pdf`,
    sections: {
      projectData: [
        { label: 'Tag Number', value: safeText(config.project.tagNumber) },
        { label: 'Order Number', value: safeText(orderNumber) },
        { label: 'Customer', value: safeText(config.project.operatorName) },
        { label: 'Date', value: generatedAt.toLocaleDateString('en-US') },
      ],
      technicalSpecifications: [
        { label: 'Model', value: modelName },
        { label: 'Nominal Size', value: `NS ${config.nominalSize} mm` },
        { label: 'Scale Range', value: `${config.rangeMin} ... ${config.rangeMax} ${config.unit}` },
        { label: 'Accuracy Class', value: deriveAccuracyClass(config.nominalSize) },
        { label: 'Case Filling', value: config.case.filling },
      ],
      materialsConnection: [
        { label: 'Mounting', value: config.options.flange },
        {
          label: 'Connection Location',
          value: config.connection.location === 'Lower' ? 'Radial (Lower)' : 'Axial (Back)',
        },
        { label: 'Thread Standard', value: config.connection.standard },
        { label: 'Movement Material', value: config.connection.material },
        { label: 'Case Material', value: config.case.material },
        { label: 'Window', value: config.case.window },
      ],
      accessories: [
        {
          label: 'Shut-Off Valve',
          value: config.accessories.valve.enabled
            ? `${config.accessories.valve.standard} ${config.accessories.valve.type}`
            : 'None',
        },
        {
          label: 'Valve Material',
          value: config.accessories.valve.enabled ? config.accessories.valve.material : '-',
        },
        {
          label: 'Siphon',
          value: config.accessories.siphon.enabled
            ? `${config.accessories.siphon.standard} ${config.accessories.siphon.type}`
            : 'None',
        },
        {
          label: 'Siphon Material',
          value: config.accessories.siphon.enabled ? config.accessories.siphon.material : '-',
        },
      ],
      options: [
        { label: 'Red Set Pointer', value: config.options.redPointer ? 'Yes' : 'No' },
        { label: 'Oxygen Service', value: config.options.oxygenService ? 'Yes' : 'No' },
        {
          label: 'Calibration Certificate',
          value: config.options.calibrationCert ? 'Included' : 'No',
        },
      ],
    },
    technicalParameters: config.otherTechnicalParams.trim() || '-',
    technicalContent: config.technicalContent,
    sketchNotes: [
      '* Dimensions are for reference only. See official catalog for exact details.',
      '* Generated from the standalone Bourdon Gauge Configurator.',
    ],
  };
};
