import { Workflow } from 'lucide-react';
import {
  ACCESSORY_MATERIALS,
  SIPHON_TYPES,
  VALVE_TYPES,
} from '@/entities/gauge-config/model/catalogs';
import { useGaugeConfiguratorStore } from '@/entities/gauge-config/model/store';
import { en } from '@/shared/i18n';
import { Field } from '@/shared/ui/Field';
import { SectionCard } from '@/shared/ui/SectionCard';
import { SelectInput } from '@/shared/ui/SelectInput';
import { ToggleSwitch } from '@/shared/ui/ToggleSwitch';

type AccessoryPanelProps = {
  title: string;
  enabled: boolean;
  onToggle: () => void;
  typeLabel: string;
  materialLabel: string;
  typeValue: string;
  materialValue: string;
  typeOptions: readonly string[];
  onTypeChange: (nextValue: string) => void;
  onMaterialChange: (nextValue: string) => void;
};

const AccessoryPanel = ({
  title,
  enabled,
  onToggle,
  typeLabel,
  materialLabel,
  typeValue,
  materialValue,
  typeOptions,
  onTypeChange,
  onMaterialChange,
}: AccessoryPanelProps) => (
  <div className="space-y-3 rounded-3xl border border-white/5 bg-white/4 p-4">
    <div className="flex items-center justify-between gap-4">
      <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-slate-300">{title}</p>
      <ToggleSwitch checked={enabled} onChange={onToggle} label={title} />
    </div>

    {enabled ? (
      <div className="grid gap-3 md:grid-cols-2">
        <Field label={typeLabel}>
          <SelectInput value={typeValue} onChange={(event) => onTypeChange(event.currentTarget.value)}>
            {typeOptions.map((option) => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </SelectInput>
        </Field>

        <Field label={materialLabel}>
          <SelectInput value={materialValue} onChange={(event) => onMaterialChange(event.currentTarget.value)}>
            {ACCESSORY_MATERIALS.map((option) => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </SelectInput>
        </Field>
      </div>
    ) : null}
  </div>
);

export const AccessoriesForm = () => {
  const accessories = useGaugeConfiguratorStore((state) => state.config.accessories);
  const toggleAccessory = useGaugeConfiguratorStore((state) => state.toggleAccessory);
  const setAccessoryField = useGaugeConfiguratorStore((state) => state.setAccessoryField);

  return (
    <SectionCard title={en.sections.accessories} icon={Workflow} accentClass="text-cyan-400">
      <div className="space-y-4">
        <AccessoryPanel
          title={en.accessories.valve}
          enabled={accessories.valve.enabled}
          onToggle={() => toggleAccessory('valve')}
          typeLabel={en.labels.valveType}
          materialLabel={en.labels.valveMaterial}
          typeValue={accessories.valve.type}
          materialValue={accessories.valve.material}
          typeOptions={VALVE_TYPES}
          onTypeChange={(value) => setAccessoryField('valve', 'type', value)}
          onMaterialChange={(value) => setAccessoryField('valve', 'material', value)}
        />

        <AccessoryPanel
          title={en.accessories.siphon}
          enabled={accessories.siphon.enabled}
          onToggle={() => toggleAccessory('siphon')}
          typeLabel={en.labels.siphonType}
          materialLabel={en.labels.siphonMaterial}
          typeValue={accessories.siphon.type}
          materialValue={accessories.siphon.material}
          typeOptions={SIPHON_TYPES}
          onTypeChange={(value) => setAccessoryField('siphon', 'type', value)}
          onMaterialChange={(value) => setAccessoryField('siphon', 'material', value)}
        />
      </div>
    </SectionCard>
  );
};

