import { z } from 'zod';
import {
  ACCESSORY_MATERIALS,
  CASE_FILLINGS,
  CASE_MATERIALS,
  CONNECTION_STANDARDS,
  GAUGE_WINDOWS,
  MOUNTING_TYPES,
  SIPHON_TYPES,
  VALVE_TYPES,
} from '@/entities/gauge-config/model/catalogs';

export const gaugeAccessorySchema = z.object({
  enabled: z.boolean(),
  type: z.string(),
  standard: z.string(),
  material: z.string(),
});

const technicalTextBlockSchema = z.object({
  id: z.string(),
  type: z.literal('text'),
  title: z.string(),
  text: z.string(),
});

const technicalTableBlockSchema = z.object({
  id: z.string(),
  type: z.literal('table'),
  title: z.string(),
  columns: z.array(z.string()),
  rows: z.array(z.array(z.string())),
});

const technicalImageBlockSchema = z.object({
  id: z.string(),
  type: z.literal('image'),
  title: z.string(),
  caption: z.string(),
  src: z.string(),
});

export const technicalContentBlockSchema = z.discriminatedUnion('type', [
  technicalTextBlockSchema,
  technicalTableBlockSchema,
  technicalImageBlockSchema,
]);

export const gaugeConfiguratorStateSchema = z.object({
  model: z.string(),
  nominalSize: z.union([z.literal(63), z.literal(100), z.literal(160)]),
  unit: z.union([z.literal('bar'), z.literal('psi'), z.literal('MPa'), z.literal('kg/cm^2')]),
  rangeMin: z.number(),
  rangeMax: z.number(),
  connection: z.object({
    location: z.union([z.literal('Lower'), z.literal('Back')]),
    standard: z.enum(CONNECTION_STANDARDS),
    material: z.string(),
  }),
  case: z.object({
    material: z.enum(CASE_MATERIALS),
    filling: z.enum(CASE_FILLINGS),
    window: z.enum(GAUGE_WINDOWS),
  }),
  accessories: z.object({
    siphon: gaugeAccessorySchema.extend({
      type: z.enum(SIPHON_TYPES),
      material: z.enum(ACCESSORY_MATERIALS),
    }),
    valve: gaugeAccessorySchema.extend({
      type: z.enum(VALVE_TYPES),
      material: z.enum(ACCESSORY_MATERIALS),
    }),
  }),
  options: z.object({
    redPointer: z.boolean(),
    flange: z.enum(MOUNTING_TYPES),
    oxygenService: z.boolean(),
    calibrationCert: z.boolean(),
  }),
  project: z.object({
    tagNumber: z.string(),
    temperature: z.number(),
    medium: z.string(),
    standard: z.string(),
    certificates: z.string(),
    orderNumber: z.string(),
    operatorName: z.string(),
  }),
  otherTechnicalParams: z.string(),
  technicalContent: z.array(technicalContentBlockSchema),
});

export const gaugeConfiguratorHydrationSchema = gaugeConfiguratorStateSchema.partial({
  model: true,
  nominalSize: true,
  unit: true,
  rangeMin: true,
  rangeMax: true,
  connection: true,
  case: true,
  accessories: true,
  options: true,
  project: true,
  otherTechnicalParams: true,
  technicalContent: true,
});
