import { create } from 'zustand';
import { defaultGaugeConfiguratorState } from '@/entities/gauge-config/model/defaults';
import { normalizeConfig, withDerivedFields } from '@/entities/gauge-config/lib/normalize-config';
import type {
  AccessoryKey,
  BooleanOptionKey,
  GaugeConfiguratorState,
  GaugeFilling,
  MountingType,
  RangePreset,
} from '@/entities/gauge-config/model/types';

type GaugeConfiguratorStore = {
  config: GaugeConfiguratorState;
  setField: <K extends keyof GaugeConfiguratorState>(field: K, value: GaugeConfiguratorState[K]) => void;
  setProjectField: <K extends keyof GaugeConfiguratorState['project']>(
    field: K,
    value: GaugeConfiguratorState['project'][K],
  ) => void;
  setCaseField: <K extends keyof GaugeConfiguratorState['case']>(
    field: K,
    value: GaugeConfiguratorState['case'][K],
  ) => void;
  setConnectionField: <K extends keyof GaugeConfiguratorState['connection']>(
    field: K,
    value: GaugeConfiguratorState['connection'][K],
  ) => void;
  setAccessoryField: (
    accessory: AccessoryKey,
    field: keyof GaugeConfiguratorState['accessories'][AccessoryKey],
    value: string | boolean,
  ) => void;
  toggleAccessory: (accessory: AccessoryKey) => void;
  toggleOption: (option: BooleanOptionKey) => void;
  setFlange: (flange: MountingType) => void;
  setRangePreset: (preset: RangePreset) => void;
  setCustomRange: (min: number, max: number) => void;
  setFilling: (filling: GaugeFilling) => void;
  resetToDefaults: () => void;
  hydrateFromPayload: (payload: unknown) => void;
};

const safeNumber = (value: number, fallback: number) => (Number.isFinite(value) ? value : fallback);

export const useGaugeConfiguratorStore = create<GaugeConfiguratorStore>((set) => ({
  config: defaultGaugeConfiguratorState,
  setField: (field, value) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        [field]: value,
      }),
    })),
  setProjectField: (field, value) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        project: {
          ...state.config.project,
          [field]: value,
        },
      }),
    })),
  setCaseField: (field, value) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        case: {
          ...state.config.case,
          [field]: value,
        },
      }),
    })),
  setConnectionField: (field, value) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        connection: {
          ...state.config.connection,
          [field]: value,
        },
      }),
    })),
  setAccessoryField: (accessory, field, value) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        accessories: {
          ...state.config.accessories,
          [accessory]: {
            ...state.config.accessories[accessory],
            [field]: value,
          },
        },
      }),
    })),
  toggleAccessory: (accessory) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        accessories: {
          ...state.config.accessories,
          [accessory]: {
            ...state.config.accessories[accessory],
            enabled: !state.config.accessories[accessory].enabled,
          },
        },
      }),
    })),
  toggleOption: (option) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        options: {
          ...state.config.options,
          [option]: !state.config.options[option],
        },
      }),
    })),
  setFlange: (flange) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        options: {
          ...state.config.options,
          flange,
        },
      }),
    })),
  setRangePreset: (preset) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        rangeMin: preset.min,
        rangeMax: preset.max,
      }),
    })),
  setCustomRange: (min, max) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        rangeMin: safeNumber(min, state.config.rangeMin),
        rangeMax: safeNumber(max, state.config.rangeMax),
      }),
    })),
  setFilling: (filling) =>
    set((state) => ({
      config: withDerivedFields({
        ...state.config,
        case: {
          ...state.config.case,
          filling,
        },
      }),
    })),
  resetToDefaults: () => set({ config: defaultGaugeConfiguratorState }),
  hydrateFromPayload: (payload) => set({ config: normalizeConfig(payload) }),
}));

